 pub fn decoding_key_from_secret(
     alg: &Algorithm,
     secret_string: &str,
 ) -> JWTResult<DecodingKey> {
     match alg {
         Algorithm::HS256 | Algorithm::HS384 | Algorithm::HS512 => {
             if secret_string.starts_with('@') {
